def solve(rows):
    kept_rows = []
    state = 6
    original_index = 0

    for row in rows:
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and '|' in row:
            weight = int(row.split('|')[1])
        elif isinstance(row, list):
            weight = sum(field for field in row if not isinstance(field, bool)) + sum(len(s) for s in row if isinstance(s, str))
        else:
            weight = 0

        if (state + weight + original_index) % 7 != 4 or original_index == len(rows) - 1:
            kept_rows.append(row)
            state = 6 if weight == 0 else (3 * state + weight) % 7
        original_index += 1

    if not kept_rows:
        return []

    blackout_rows = [row for row in kept_rows if row[1] == True]
    eligible_days = [day for day in kept_rows if day[1] != True and day[0] % 8 != 0]

    distinct_days = sorted(list(set(day[0] for day in eligible_days)))
    return distinct_days[:2]

